      if (typeof corrMatrix === 'function') { const lab = {}; ks.forEach(k => { lab[k] = nm[k] + ' ' + Math.round(D.weights[k] * 100) + '%'; }); corrMatrix(R('#idxCorr'), { keys: ks, labels: lab, matrix: M, caption: 'Correlation of the index components across Texas counties', corner: 'Component and weight' }); } else R('#idxCorr').innerHTML = `<div class="tblbox"><div class="tblwrap"><table class="t corr"><caption class="vh">Correlation of the index components</caption><thead><tr><th scope="col">Component</th>${ks.map(k => `<th scope="col">${esc(nm[k])}</th>`).join('')}</tr></thead><tbody>${ks.map(a => `<tr><th scope="row">${esc(nm[a])} <span class="small">${Math.round(D.weights[a] * 100)}%</span></th>${ks.map(b => { const v = M[a][b]; const bg = isN(v) && a !== b ? divergeColor(v) : 'var(--sunk)'; return `<td style="background:${bg};color:${a === b ? 'var(--ink-3)' : inkOn(bg)}">${isN(v) ? MINUS(v.toFixed(2)) : NA}</td>`; }).join('')}</tr>`).join('')}</tbody></table></div></div>`;
      const pairs = []; ks.forEach((a, i) => ks.slice(i + 1).forEach(b => { if (isN(M[a][b])) pairs.push([a, b, M[a][b]]); })); pairs.sort((x, y) => Math.abs(y[2]) - Math.abs(x[2])); const s0 = pairs[0], w0 = pairs[pairs.length - 1];
      const mv = VAL.movers.filter(m => m.d);
