      const gcol = g => g === 'A' ? 'var(--s1)' : g === 'B' ? 'var(--s3)' : 'var(--s4)'; const gkey = cd => `<span class="legendc"><span><i style="background:var(--s1)"></i>Grade A</span><span><i style="background:var(--s3)"></i>Grade B</span>${cd ? '<span><i style="background:var(--s4)"></i>Grade C or D</span>' : ''}</span>`;
