      R('#idxSc2n').innerHTML = gkey(true) + `<b>Out of time:</b> Pearson r ${N(VAL.ytd.di.r, 2)} (95% interval ${N(VAL.ytd.di.lo, 2)} to ${N(VAL.ytd.di.hi, 2)}), Spearman ρ ${N(VAL.ytd.di.rho, 2)}, ${N(VAL.ytd.di.n)} counties with monthly reports, no reporting gap and 50 or more filings in the same months of 2025. ${VAL.v.ytdDi === 'fails' ? 'This check fails.' : VAL.v.ytdDi === 'weak' ? 'Positive but weak.' : 'This check holds.'}`;
      const vt = v => v === 'holds' ? '<span class="pill good">holds</span>' : v === 'weak' ? '<span class="pill p-warn">weak</span>' : v === 'fails' ? '<span class="pill bad">fails</span>' : '<span class="pill">n/a</span>';
      const row = (name, what, t, v) => `<tr><td class="l wrap"><b>${esc(name)}</b><div class="small">${esc(what)}</div></td><td>${N(t.r, 2)}</td><td>${N(t.rho, 2)}</td><td>${N(t.n)}</td><td>${isN(t.p) ? (t.p < 0.001 ? 'under 0.001' : N(t.p, 3)) : NA}</td><td>${vt(v)}</td></tr>`;
